import{_ as a,o as t,c as i,a4 as r}from"./chunks/framework.C5O7Kvow.js";const u=JSON.parse('{"title":"Data Grid API map","description":"Map Data Grid visual surfaces, editing helpers, filtering, footer, export, and personalization APIs to their owning packages.","frontmatter":{"title":"Data Grid API map","description":"Map Data Grid visual surfaces, editing helpers, filtering, footer, export, and personalization APIs to their owning packages."},"headers":[],"relativePath":"components/data-grid/api.md","filePath":"components/data-grid/api.md"}'),d={name:"components/data-grid/api.md"};function o(s,e,n,p,c,l){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="data-grid-api-map" tabindex="-1">Data Grid API map <a class="header-anchor" href="#data-grid-api-map" aria-label="Permalink to &quot;Data Grid API map&quot;">​</a></h1><p>The Data Grid hub spans <code>@jsvision/ui</code> and <code>@jsvision/datagrid</code>. This map keeps package ownership visible: use the UI package for the compact read-only surface and the Data Grid package for typed editing, transformations, aggregation, and personalization.</p><h2 id="visual-surfaces" tabindex="-1">Visual surfaces <a class="header-anchor" href="#visual-surfaces" aria-label="Permalink to &quot;Visual surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Package</th><th>Role</th></tr></thead><tbody><tr><td><a href="/jsvision/pr-preview/pr-195/api/ui/classes/DataGrid.html"><code>DataGrid</code></a></td><td><code>@jsvision/ui</code></td><td>Compact read-only grid</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/ui/classes/GridHeader.html"><code>GridHeader</code></a></td><td><code>@jsvision/ui</code></td><td>Read-only column header</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/ui/classes/GridRows.html"><code>GridRows</code></a></td><td><code>@jsvision/ui</code></td><td>Read-only row viewport</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/datagrid/classes/EditableDataGrid.html"><code>EditableDataGrid</code></a></td><td><code>@jsvision/datagrid</code></td><td>Typed interactive grid</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/datagrid/classes/EditableGridRows.html"><code>EditableGridRows</code></a></td><td><code>@jsvision/datagrid</code></td><td>Editable row viewport</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/datagrid/classes/SortHeader.html"><code>SortHeader</code></a></td><td><code>@jsvision/datagrid</code></td><td>Sort state and priority</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/datagrid/classes/QuickFilterRow.html"><code>QuickFilterRow</code></a></td><td><code>@jsvision/datagrid</code></td><td>Per-column quick filters</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/datagrid/classes/FilterPopup.html"><code>FilterPopup</code></a></td><td><code>@jsvision/datagrid</code></td><td>Condition filter editor</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/datagrid/classes/ValueList.html"><code>ValueList</code></a></td><td><code>@jsvision/datagrid</code></td><td>Distinct-value selection</td></tr><tr><td><a href="/jsvision/pr-preview/pr-195/api/datagrid/classes/FooterBand.html"><code>FooterBand</code></a></td><td><code>@jsvision/datagrid</code></td><td>Aggregate footer surface</td></tr></tbody></table><h2 id="ownership-boundaries" tabindex="-1">Ownership boundaries <a class="header-anchor" href="#ownership-boundaries" aria-label="Permalink to &quot;Ownership boundaries&quot;">​</a></h2><p>The host owns domain rows, persistence, authorization, and remote source policy. The grid owns viewport interaction and the configured transformation/edit lifecycle. Export callers own scope and destination safety; <code>personalizeGrid</code> owns the reversible dialog interaction, while the host owns variant persistence and migration.</p><p>Supporting column, editor, validation, source, export, and variant types live beside <code>EditableDataGrid</code> in <code>@jsvision/datagrid</code>. Import through the package entry point so examples and applications remain independent of workspace source layout.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/jsvision/pr-preview/pr-195/components/data-grid/">Overview</a> — choose the correct surface.</li><li><a href="/jsvision/pr-preview/pr-195/components/data-grid/editing-and-editors.html">Editing &amp; cell editors</a> — learn the edit lifecycle.</li><li><a href="/jsvision/pr-preview/pr-195/components/data-grid/export-and-personalization.html">Export &amp; personalization</a> — apply the trust and ownership boundaries.</li><li><a href="/jsvision/pr-preview/pr-195/api/datagrid/functions/personalizeGrid.html"><code>personalizeGrid</code> API</a> — generated helper signature.</li></ul>',9)])])}const v=a(d,[["render",o]]);export{u as __pageData,v as default};
